(function () {
  'use strict';
  function mount() {
    var nav = document.querySelector('.App-nav .Dropdown-menu, .AdminNav .Dropdown-menu, nav.AdminNav ul');
    if (!nav || nav.querySelector('.lmx-store-adminlink')) return;
    var li = document.createElement('li');
    li.className = 'lmx-store-adminlink';
    var a = document.createElement('a');
    a.className = 'Button Button--link';
    a.href = '/store/admin';
    a.target = '_blank';
    a.rel = 'noopener';
    a.textContent = 'Store';
    a.title = 'Catalogue, orders, balances and the audit trail';
    li.appendChild(a);
    nav.appendChild(li);
  }
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', mount);
  } else {
    mount();
  }
  new MutationObserver(function () { mount(); })
    .observe(document.documentElement, { childList: true, subtree: true });
})();

(function () {
  var TPL = null;
  function tpl() {
    if (TPL === null) {
      var el = document.getElementById('lmx-index-template');
      TPL = el ? el.textContent : '';
    }
    return TPL;
  }
  function isIndex() {
    // front page only. /all is the discussion list and previously got the
    // index stacked on top of it.
    var p = location.pathname;
    return p === '/' || p === '' || p === '/tags';
  }
  function mount() {
    var host = document.querySelector('.IndexPage-results, .TagsPage-content, .IndexPage');
    if (!host) return;
    var existing = document.querySelector('.LmxIndex');
    if (!isIndex()) { if (existing) existing.remove(); return; }
    if (existing && existing.isConnected) return;
    var wrap = document.createElement('div');
    wrap.innerHTML = tpl();
    var node = wrap.firstElementChild;
    if (!node) return;
    host.parentNode.insertBefore(node, host);
    document.body.classList.add('lmx-index-on');
  }
  function tick() { try { mount(); } catch (e) {} }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', tick);
  else tick();
  setInterval(tick, 700);
  window.addEventListener('popstate', tick);
})();
